    ano: 2025,
    num: 199,
    conImagen: false,
    enunciado: "Paciente de 76 años, sin comorbilidad conocida que sufre una caída casual desde una escalera sufriendo un traumatismo craneal y cervical. Atendido inicialmente por un familiar, que le coloca en posición lateral de seguridad mientras espera la llegada de las asistencias sanitarias. A la llegada del personal del SAMU el paciente se encuentra inconsciente. ¿Cuál de las siguientes afirmaciones es FALSA sobre el manejo de la vía aérea?:",
